<template><div class="diagnostics-page"><div class="page-heading"><div><h1>运行诊断</h1><p>查看当前会话、导航、契约版本和前端能力状态。</p></div><el-button :loading="loading" @click="refresh"><el-icon><Refresh /></el-icon>刷新</el-button></div><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" /><el-row :gutter="16"><el-col :xs="24" :lg="8"><el-card shadow="never"><template #header>当前会话</template><el-descriptions :column="1" border><el-descriptions-item label="用户">{{ session.displayName }}</el-descriptions-item><el-descriptions-item label="账号">{{ session.user?.login || '—' }}</el-descriptions-item><el-descriptions-item label="公司">{{ session.user?.company_name || '—' }}</el-descriptions-item><el-descriptions-item label="管理员"><el-tag :type="session.isAdmin?'success':'info'">{{ session.isAdmin?'是':'否' }}</el-tag></el-descriptions-item></el-descriptions></el-card></el-col><el-col :xs="24" :lg="8"><el-card shadow="never"><template #header>运行时概览</template><el-descriptions :column="1" border><el-descriptions-item label="菜单数量">{{ menuCount }}</el-descriptions-item><el-descriptions-item label="角色">{{ String(session.roleSurface.role_label||session.roleSurface.primary_role_code||'—') }}</el-descriptions-item><el-descriptions-item label="后端版本">{{ session.user?'Odoo 17':'—' }}</el-descriptions-item><el-descriptions-item label="会话状态"><el-tag type="success">已初始化</el-tag></el-descriptions-item></el-descriptions></el-card></el-col><el-col :xs="24" :lg="8"><el-card shadow="never"><template #header>前端能力</template><el-tag v-for="item in capabilities" :key="item" class="capability" effect="plain">{{ item }}</el-tag></el-card></el-col></el-row><el-card shadow="never"><template #header>导航契约</template><pre>{{ JSON.stringify(session.navigation, null, 2) }}</pre></el-card></div></template>
<script setup lang="ts">import { computed,ref } from 'vue';import { ElMessage } from 'element-plus';import { Refresh } from '@element-plus/icons-vue';import { fetchIntentCatalog } from '@/api/odoo';import { useSessionStore } from '@/stores/session';const session=useSessionStore();const loading=ref(false);const error=ref('');const capabilities=ref(['system.init','ui.contract.v2','api.data','execute_button','route.authority.validate']);const menuCount=computed(()=>session.navigation.length);async function refresh(){loading.value=true;error.value='';try{const result=await fetchIntentCatalog();const list=result.intents||result.intent_catalog?.map((i:any)=>String(i.key||i.name||'')).filter(Boolean)||[];if(list.length)capabilities.value=list}catch(cause){error.value=cause instanceof Error?cause.message:'能力目录加载失败';ElMessage.warning(error.value)}finally{loading.value=false}}void refresh()</script><style scoped>.diagnostics-page{display:grid;gap:16px}.page-heading{display:flex;justify-content:space-between}.page-heading h1{margin:0 0 8px;font-size:26px}.page-heading p{margin:0;color:#909399}.capability{margin:0 8px 8px 0}pre{margin:0;max-height:420px;overflow:auto;background:#f5f7fa;padding:16px;border-radius:4px;font-size:12px;line-height:1.6}</style>
